      SwfShape.draw(ctx, ART[219]);
      font(ctx, 12, "bold");
      // "road" and "lake", centred where the SWF's static labels are (214.6 + 30.6 / 2, 215.85 + 28.1 / 2)
      ctx.fillStyle = "#666666"; FlashText.fillStatic(ctx, t("px.road"), 229.9 - FlashText.widthStatic(ctx, t("px.road")) / 2, 498.6 + 12, "left");
      ctx.fillStyle = "#018389"; FlashText.fillStatic(ctx, t("px.lake"), 229.9 - FlashText.widthStatic(ctx, t("px.lake")) / 2, 5.25 + 12, "left");
      SwfShape.draw(ctx, ART[222]);
      if (showBoat) { ctx.save(); ctx.translate(boat.x, boat.y); SwfShape.draw(ctx, ART[229]); ctx.restore(); }
